yakit.AutoInitYakit()

# nuclei 快速启动插件
targets = cli.String("targets")
targets = str.SplitAndTrim(targets, "\n")
tags = cli.String("tags") # 筛选
severity = cli.String("severity")
proxy = cli.String("proxy") # 代理设置
rateLimit =cli.Int("rateLimit") # 每秒最大请求数
workflows = cli.String("workflows") # 特定 workflow 来扫描
templates = cli.String("templates") # 设置想要扫描的 templates 或者存放 templates 的目录
reverseUrl = cli.String("reverseUrl") # 反连 URL
getConfig = func(){
    ret = []
    if (severity!=""){
        # 等级 以,分割
        severity = str.SplitAndTrim(severity, ",")
        ret = append(ret,nuclei.severity(severity...))
    }else{
        ret = append(ret,nuclei.severity("low", "medium", "high", "critical"))
    }
    if (proxy!=""){
        # 代理
        ret = append(ret,nuclei.proxy(proxy))
    }
    if (tags!=""){
        # tags
        ret = append(ret,nuclei.tags(tags))
    }
    if (reverseUrl!=""){
        # 代理
        ret = append(ret,nuclei.reverseUrl(reverseUrl))
    }
    if (rateLimit!=150){
        # 每秒最大请求数
        ret = append(ret,nuclei.rateLimit(rateLimit))
    }
    if (templates!=""){
        # 设置想要扫描的 templates 或者存放 templates 的目录

        ret = append(ret,nuclei.templates(templates))
    }
    if (workflows !=""){
        # 特定 workflow 来扫描
        ret = append(ret,nuclei.workflows(workflows))
    }
    //添加超时时间
    ret = append(ret,nuclei.timeout(600))
    return ret
}
aliveIs = func(url){
    // 存活检测函数
    isHttps,packet,_ = poc.ParseUrlToHTTPRequestRaw("GET",url)
    sendPacket = func(packet) {
        return poc.HTTP(
            packet, 
            poc.timeout(3),
            # poc.proxy("http://127.0.0.1:8083"), # debug
            # poc.proxy("http://127.0.0.1:7890"),
            poc.redirectTimes(0),  # 重定向次数
            poc.https(isHttps),
        )
    }
    rsp,req,err = sendPacket(packet)
    if err!=nil{
        return false
    }else{
        return true
    }
}


wg = sync.NewSizedWaitGroup(10)
func submitTask(tg) {
    go func{
        defer wg.Done()
        config = getConfig()
        # println(config)
        start = time.now()
        yakit.Info("[!]开始扫描 %v",tg)
        res, err = nuclei.Scan(tg,config...)
        //res, err = nuclei.Scan(tg,nuclei.timeout(300))
        if err != nil {
            yakit.Info("扫描错误：%v",tg)
            return 
        }

        for result = range res {
            PocName = result.PocName
            Severity = result.Severity
            yakit.Info("[+]%v 发现漏洞: [%v] 级别：[%v]",tg,PocName,Severity)
            risk_ = nuclei.PocVulToRisk(result)
            }
        since = time.Since(start).Seconds()
        yakit.Info("[!]%v扫描完毕 耗时%vs",tg,since)
        //close(res)
    }
}
for _,tg := range targets{
    tg = tg
    //存活检测
    if (aliveIs(tg) == false){
        yakit.Info("[-]%v不可到达！",tg)
        continue
    }
    wg.Add()
    # yakit.Info(tg) # debug
    submitTask(tg)
    time.sleep(0.2)
}
 wg.Wait()
